@startuml

class School {
  + Name : string
}

class Person {
  + FirstName : string
  + LastName : string
}

class Teacher extends Person {
  + EmailAddress : string
}

class Student extends Person {
}

class TeachingRelationship {
  + Hours : int
}

class ClassGroup {
  + Name : string
}

class Room {
  + Name : string
}

class Classroom extends Room {
  + Capacity : int
}

class Gym extends Room {
  + Size : float
}

School "1" -- "1..3" Teacher : employs
School "1" -- "1" Teacher : principal
School "1" -- "*" TeachingRelationship
Teacher "1" -- "*" TeachingRelationship
TeachingRelationship "1" -- "1" School

Student "1" -- "1" ClassGroup
ClassGroup "1" -- "1" Classroom
ClassGroup "1" -- "10..31" Student

School "1" *-- "*" Room

@enduml

